head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst36910";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.dtruleLawNo

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst36910.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_dtruleLawNo", fn: function(){ return (!(String(((dma_pageContext.get("dtruleLawNo") ?? "")) == null ? '' : ((dma_pageContext.get("dtruleLawNo") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.initValue();
        $(document).find('h2[id=txt_law1Title]').append(dma_hiddenStore.get("law1TitleVal"));
        $(document).find('h2[id=txt_law2Title]').append(dma_hiddenStore.get("law2TitleVal"));
        $(document).find('div[id=dialog-loading]').css("display", "none");

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst36910.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_GetLawItemContents_xhr
 * @description Get Law Item Contents xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GetLawItemContents_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_GetLawItemContents_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_GetLawItemContents_xhr", unresolved: "action:self_submit:tx_fn_GetLawItemContents_xhr" };
};

/**
 * @method
 * @name tx_fn_GetLawDtruleItemContents_xhr
 * @description Get Law Dtrule Item Contents xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GetLawDtruleItemContents_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_GetLawDtruleItemContents_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_GetLawDtruleItemContents_xhr", unresolved: "action:self_submit:tx_fn_GetLawDtruleItemContents_xhr" };
};

/**
 * @method
 * @name initValue
 * @description init Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initValue = async function () {
    await scwin.getLawItemContents();
    await scwin.getLawDtruleItemContents();
};

/**
 * @method
 * @name getLawItemContents
 * @description get Law Item Contents 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getLawItemContents = async function () {
    $c.util.getComponent('ipt_method').setValue("viewLawItem");
    const result = await scwin.tx_fn_GetLawItemContents_xhr();
    $("#law1").append(result);
};

/**
 * @method
 * @name getLawDtruleItemContents
 * @description get Law Dtrule Item Contents 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getLawDtruleItemContents = async function () {
    $c.util.getComponent('ipt_method').setValue("viewLawDtruleItem");
    let result = await scwin.tx_fn_GetLawDtruleItemContents_xhr();
    result = scwin.trim(result);
    if (result !== '' || result != null) {
        $("#law2").append(result);
    }
};

/**
 * @method
 * @name trim
 * @description trim 처리
 * @param {*} _str _str
 * @returns {void}
 * @hidden N
 */
scwin.trim = function (_str) {
    return _str.replace(/^\s{1,}/, "").replace(/\s{1,}$/, "");
};
